"""Helpers for writing OpenFOAM dictionaries."""

from __future__ import annotations

from typing import Iterable


def header(obj: str, cls: str = "dictionary") -> str:
    return (
        "/*--------------------------------*- C++ -*----------------------------------*\\\n"
        "  Generated by rocketcfd\n"
        "\\*---------------------------------------------------------------------------*/\n"
        f"FoamFile\n{{\n    version     2.0;\n    format      ascii;\n"
        f"    class       {cls};\n    object      {obj};\n}}\n\n"
    )


def vec(v: Iterable[float]) -> str:
    return "(" + " ".join(f"{x:.9g}" for x in v) + ")"


def num(x: float) -> str:
    return f"{x:.9g}"
